46	// Fetch returns the files of the template at src, or an error saying why it
47	// cannot be used — including that it is larger than a template may be.
48	func Fetch(ctx context.Context, src Source, creds Credentials) ([]File, error) {
49		files, err := fetch(ctx, src, creds)
50		if err != nil {
51			return nil, err
52		}
53		if err := checkLimits(files); err != nil {
54			return nil, err
55		}
56		return files, nil
57	}
58	
59	// checkLimits refuses a template past MaxFiles or MaxBytes, naming the biggest
60	// file so the reader knows where to look. It runs before anything is created on
61	// the forge: a refusal after the repository exists would leave an empty one.
62	func checkLimits(files []File) error {
63		if len(files) > MaxFiles {
64			return fmt.Errorf("the template has %d files, more than the %d a template may have", len(files), MaxFiles)
65		}
66	
67		total, biggest := 0, File{}
68		for _, f := range files {
69			total += len(f.Content)
70			if len(f.Content) > len(biggest.Content) {
71				biggest = f
72			}
73		}
74		if total > MaxBytes {
75			return fmt.Errorf("the template is %s, more than the %s a template may be — the largest file is %s (%s)",
76				FormatSize(total), FormatSize(MaxBytes), biggest.Path, FormatSize(len(biggest.Content)))
77		}
78		return nil
79	}
