81	// FormatSize writes a byte count the way the application says it: 1.5 MiB.
82	func FormatSize(n int) string {
83		switch {
84		case n >= 1<<20:
85			return fmt.Sprintf("%.1f MiB", float64(n)/(1<<20))
86		case n >= 1<<10:
87			return fmt.Sprintf("%.1f KiB", float64(n)/(1<<10))
88		default:
89			return fmt.Sprintf("%d B", n)
90		}
91	}
