93	func fetch(ctx context.Context, src Source, creds Credentials) ([]File, error) {
94		if err := src.Validate(); err != nil {
95			return nil, err
96		}
97	
98		switch src.Kind {
99		case KindGit:
100			raw, err := git.ArchiveRemote(ctx, src.URL, src.Ref, src.Path, creds.Token, archiveCap)
101			if err != nil {
102				return nil, tooLargeOr(fmt.Errorf("fetching %s: %w", src.URL, err), err)
103			}
104			return readArchive(raw)
